QSet<QString> owned(const QJsonObject& p,bool points){QSet<QString> r;for(const auto& v:p["rotateGroups"].toArray()){const auto g=v.toObject();if(points)for(const auto& s:g["sourcePoints"].toArray())r.insert(s.toObject()["pointId"].toString());else for(const auto& id:g["entityIds"].toArray())r.insert(id.toString());}return r;}
bool touches(const QJsonObject& p,const QJsonValue& v){return mentions(v,owned(p)+owned(p,true));}
