QJsonObject source(const QJsonObject& p){auto r=p;auto points=p["points"].toArray();for(const auto& v:p["rotateGroups"].toArray())for(const auto& s:v.toObject()["sourcePoints"].toArray())for(int n=0;n<points.size();++n)if(points[n].toObject()["id"]==s.toObject()["pointId"]){auto point=points[n].toObject();point["uMm"]=s.toObject()["uMm"];point["vMm"]=s.toObject()["vMm"];points[n]=point;}r["points"]=points;r.remove("rotateGroups");return r;}
QJsonObject materialize(const QJsonObject& p,const QJsonArray& groups){auto r=p;auto points=p["points"].toArray();for(const auto& v:groups){const auto g=v.toObject(),a=axis(p,g);for(const auto& v:g["sourcePoints"].toArray()){const auto s=v.toObject(),out=output(s,a,g["angleDeg"].toDouble());finite(out,"uMm");finite(out,"vMm");bool found=false;for(int n=0;n<points.size();++n)if(points[n].toObject()["id"]==s["pointId"]){auto point=points[n].toObject();point["uMm"]=out["uMm"];point["vMm"]=out["vMm"];points[n]=point;found=true;}need(found,"Rotate source point is unavailable");}}r["points"]=points;if(!groups.isEmpty())r["rotateGroups"]=groups;return r;}
std::optional<SketchSolver::SourceOrientation> orientation(const QJsonObject& p){for(const auto& v:p["rotateGroups"].toArray()){const auto f=v.toObject()["sourceFrame"].toObject();if(!f.isEmpty())return SketchSolver::SourceOrientation{f["anchorPointId"].toString(),f["headingPointId"].toString(),f["headingAngleRad"].toDouble()};}return {};}
QSet<QString> anchors(const QJsonObject& p){QSet<QString> r;if(const auto f=orientation(p))r.insert(f->anchorPointId);return r;}
void verifySource(const QJsonObject& p,const QJsonObject& solved){const auto actual=rows(solved,"points");for(const auto& v:p["rotateGroups"].toArray()){const auto g=v.toObject();if(!g.contains("sourceFrame"))continue;for(const auto& v:g["sourcePoints"].toArray()){const auto s=v.toObject(),a=actual.value(s["pointId"].toString());need(!a.isEmpty(),"Rotate source solver changed point membership");for(const auto* key:{"uMm","vMm"})need(std::abs(a[key].toDouble()-s[key].toDouble())<=1e-6,"Rotate source solve changed authoritative coordinates outside a source-size transaction");}}}
